def problem(t, eps, keep):
    from scipy.signal import lfilter
    dt = np.diff(t)
    dx = np.diff(eps)
    uniform = np.allclose(dt, dt[0], rtol=1e-10, atol=0)
    ds = dt[0] if uniform else dt
    D = np.c_[np.ones(len(t)), (t - t.mean()) / np.ptp(t)][keep]
    Q = np.linalg.qr(D)[0]

    def proj(a):
        return a - Q @ (Q.T @ a)

    def columns(logs, derivative=False):
        K = np.empty((len(t), 1 + len(logs)))
        K[:, 0] = eps
        H = np.zeros((len(t), len(logs))) if derivative else None
        for (j, log) in enumerate(logs):
            x = ds * np.exp(-log)
            a = np.exp(-x)
            c = -np.expm1(-x) / x
            q = K[:, j + 1]
            q[0] = 0.0
            if uniform:
                q[1:] = lfilter([c], [1.0, -a], dx)
                if derivative:
                    H[1:, j] = lfilter([1.0], [1.0, -a], x * a * q[:-1] + (c - a) * dx)
            else:
                for i in range(len(dx)):
                    q[i + 1] = a[i] * q[i] + c[i] * dx[i]
                    if derivative:
                        H[i + 1, j] = a[i] * (H[i, j] + x[i] * q[i]) + (c[i] - a[i]) * dx[i]
        return (proj(K[keep]), proj(H[keep]) if derivative else None)
    return (proj, columns)

def build(t, e, tau, kind):
    from scipy.signal import lfilter
    dt = np.diff(t)[:, None]
    dx = np.diff(e)[:, None]
    x = dt / tau
    if kind == 'euler':
        a = 1 - x
        c = 1
    elif kind == 'backward_euler':
        a = 1 / (1 + x)
        c = a
    else:
        a = np.exp(-x)
        c = {'linear': lambda : -np.expm1(-x) / x, 'right': lambda : 1, 'left': lambda : a, 'mid': lambda : np.exp(-x / 2), 'trapezoid': lambda : (1 + a) / 2}[kind]()
    q = np.zeros((len(t), len(tau)))
    f = c * dx * np.ones_like(a)
    if np.allclose(dt, dt[0], atol=0, rtol=1e-10):
        for (k, v) in enumerate(a[0]):
            q[1:, k] = lfilter([1.0], [1.0, -v], f[:, k])
    else:
        for k in range(len(dt)):
            q[k + 1] = a[k] * q[k] + f[k]
    return np.column_stack((e, q))
